<script setup lang="ts">
import { computed } from 'vue'
import type { QualitySummary } from './api'
const props = defineProps<{ data: QualitySummary }>()
const circumference = 2*Math.PI*66
const ratio = computed(() => props.data.total ? props.data.positive/props.data.total : 0)
const max = computed(() => Math.max(2,...props.data.trend.map(t => Math.max(t.positive,t.negative))))
const x = (i: number) => 42+(props.data.trend.length > 1 ? i/(props.data.trend.length-1) : .5)*530
const y = (n: number) => 160-n/max.value*120
const line = (key: 'positive' | 'negative') => props.data.trend.map((t,i) => `${x(i)},${y(t[key])}`).join(' ')
const ticks = computed(() => [...new Set([0,Math.floor(props.data.trend.length/2),props.data.trend.length-1])].filter(i => i>=0))
</script>
<template><div class="quality-chart-grid"><section class="panel-card quality-chart"><h2>评价分布</h2><p>优秀与不佳评价的占比</p><svg viewBox="0 0 260 205" role="img" :aria-label="`优秀${data.positive}条，不佳${data.negative}条，好评率${data.positiveRate}%`"><circle cx="130" cy="95" r="66" fill="none" :stroke="data.total ? '#d88c91' : 'var(--el-border-color)'" stroke-width="14" /><circle cx="130" cy="95" r="66" fill="none" stroke="#69a994" stroke-width="14" :stroke-dasharray="`${ratio*circumference} ${circumference}`" transform="rotate(-90 130 95)" /><text x="130" y="93" text-anchor="middle" fill="currentColor" font-size="26">{{ data.total ? data.positiveRate+'%' : '—' }}</text><text x="130" y="117" text-anchor="middle" fill="currentColor" font-size="12">{{ data.total ? '好评率' : '暂无评价' }}</text></svg><div class="quality-legend"><span>● 回复优秀</span><span>● 回复不佳</span></div></section><section class="panel-card quality-chart"><h2>评价趋势</h2><p>按最近一次评价或修改的日期统计当前有效评价</p><svg viewBox="0 0 600 205" role="img" aria-label="每日优秀与不佳评价趋势"><g v-for="v in [0,.5,1]" :key="v"><path :d="`M42 ${y(max*v)}H572`" stroke="var(--el-border-color-light)" /><text x="30" :y="y(max*v)+4" text-anchor="end" fill="currentColor" font-size="11">{{ Math.round(max*v) }}</text></g><g v-for="key in (['positive','negative'] as const)" :key="key"><polyline :points="line(key)" fill="none" :stroke="key === 'positive' ? '#69a994' : '#d88c91'" stroke-width="2" /><circle v-for="(t,i) in data.trend" :key="t.date" :cx="x(i)" :cy="y(t[key])" r="3" :fill="key === 'positive' ? '#69a994' : '#d88c91'"><title>{{ t.date }} {{ key === 'positive' ? '优秀' : '不佳' }} {{ t[key] }}条</title></circle></g><text v-for="i in ticks" :key="i" :x="x(i)" y="188" text-anchor="middle" fill="currentColor" font-size="11">{{ data.trend[i]?.date.slice(5) }}</text></svg><div class="quality-legend"><span>● 回复优秀</span><span>● 回复不佳</span></div><details><summary>查看每日数据</summary><div v-for="t in data.trend" :key="t.date">{{ t.date }}：优秀 {{ t.positive }}，不佳 {{ t.negative }}</div></details></section></div></template>
<style scoped>.quality-chart-grid{display:grid;grid-template-columns:1fr 2fr;gap:18px;margin:20px 0}.quality-chart{padding:24px;min-width:0;color:var(--el-text-color-secondary)}.quality-chart h2{font-size:15px;color:var(--el-text-color-primary);margin:0 0 8px}.quality-chart p,.quality-chart details{font-size:12px;line-height:1.7;color:var(--el-text-color-secondary)}.quality-chart svg{display:block;width:100%;max-height:230px}.quality-legend{display:flex;justify-content:center;gap:20px;font-size:12px}.quality-legend span:first-child{color:#69a994}.quality-legend span:last-child{color:#d88c91}.quality-chart details{margin-top:12px}.quality-chart summary{cursor:pointer}@media(max-width:900px){.quality-chart-grid{grid-template-columns:1fr}}</style>
